import { Parser, ReplacementRules, popKeys, hasKey, isDict } from './parser';
import { Generators, createPromptInfo, createSampler, createModel, createPrompt, PromptInfo, Model } from '../data';
import { ParserError } from '../exceptions';
import { loadJson } from '../utils/json';

const SAMPLER_PARAMS = ['seed', 'strength', 'noise', 'scale'];
const REPLACEMENT_RULES: ReplacementRules = [['scale', 'cfg_scale']];

/**
 * Parser for images generated by NovelAI
 */
export class NovelAIParser extends Parser {
  public readonly generator = Generators.NOVELAI;

  async parse(parameters: Record<string, any>): Promise<PromptInfo> {
    let metadata: Record<string, any>;
    let params: unknown;
    let source: unknown;

    try {
      metadata = loadJson(parameters.Comment);
      if (!hasKey(parameters, 'Description') || !hasKey(parameters, 'Source')) {
        throw new Error('missing Description or Source');
      }
      params = parameters.Description;
      source = parameters.Source;
    } catch (error) {
      throw new ParserError(`error reading parameter values: ${error}`);
    }

    if (!isDict(metadata) || !hasKey(metadata, 'sampler')) {
      throw new ParserError('no sampler found');
    }
    if (typeof params !== 'string') {
      throw new ParserError('error reading parameter values: Description');
    }

    const samplerName = metadata.sampler;
    delete metadata.sampler;
    const samplerParameters = this.normalizeParameters(popKeys(SAMPLER_PARAMS, metadata), REPLACEMENT_RULES);

    const prompts = [createPrompt(params.trim())];

    const negativePrompts = [];
    if (hasKey(metadata, 'uc')) {
      negativePrompts.push(createPrompt(metadata.uc));
      delete metadata.uc;
    }

    // model
    let model: Model | undefined;
    const match = typeof source === 'string' ? /^(.*?)\s+([A-Z0-9]+)$/.exec(source) : null;
    if (match) {
      model = createModel({ name: match[1], hash: match[2] });
    }

    const sampler = createSampler(samplerName, samplerParameters, { model, prompts, negativePrompts });

    return createPromptInfo(this.generator, [sampler], metadata, parameters);
  }
}
